CREATE TABLE `chat_geniuses` (
  `id` int UNSIGNED NOT NULL,
  `chat_genius_id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `chat_genius_image` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `chat_genius_name` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `chat_genius_expert` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `chat_genius_description` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `chat_genius_message` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` int NOT NULL DEFAULT '1',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE `docu_assists` (
  `id` int UNSIGNED NOT NULL,
  `docu_assist_id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `generate_by` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `docu_title` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `docu_input_file` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `docu_output_response` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` int NOT NULL DEFAULT '1',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ALTER TABLE `chat_geniuses` ADD PRIMARY KEY (`id`);

ALTER TABLE `docu_assists` ADD PRIMARY KEY (`id`);

ALTER TABLE `chat_geniuses` MODIFY `id` int UNSIGNED NOT NULL AUTO_INCREMENT, AUTO_INCREMENT=56;

ALTER TABLE `docu_assists` MODIFY `id` int UNSIGNED NOT NULL AUTO_INCREMENT;

CREATE TABLE `chats` (
  `id` int UNSIGNED NOT NULL,
  `chat_id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `chat_type` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'chat',
  `generate_by` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `chat_genius_id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `chat_title` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `word_count` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0',
  `status` int NOT NULL DEFAULT '1',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `chat_messages` (
  `id` int UNSIGNED NOT NULL,
  `chat_message_id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `chat_id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `responsed_by` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'system',
  `chat_message` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` int NOT NULL DEFAULT '1',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ALTER TABLE `chats` ADD PRIMARY KEY (`id`);

ALTER TABLE `chat_messages` ADD PRIMARY KEY (`id`);

ALTER TABLE `chats` MODIFY `id` int UNSIGNED NOT NULL AUTO_INCREMENT;

ALTER TABLE `chat_messages` MODIFY `id` int UNSIGNED NOT NULL AUTO_INCREMENT;


